/* Software-in-the-loop test of DemoSwc on the PC: the Embedded Coder code of the model together
 * with the RTE generated by tools/rtegen, stimulated through the RTE buffers.
 * Build and run: see swc/README.md
 * Optional argument: path of a CSV file receiving one line per runnable call (inputs and outputs
 * after the call), compared against the MIL simulation by tools/swc/swc_mil_test.m. */

#include "Rte_DemoSwc.h"
#include "Rte_Internal.h"

#include <stdio.h>

static int failures = 0;
static int checks   = 0;

static FILE* trace    = NULL; /* optional per-call trace (CSV) */
static unsigned calls = 0U;

#define CHECK(cond)                                                            \
    do                                                                         \
    {                                                                          \
        ++checks;                                                              \
        if (!(cond))                                                           \
        {                                                                      \
            ++failures;                                                        \
            printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);           \
        }                                                                      \
    } while (0)

static void traceCall(char const* runnable)
{
    ++calls;
    if (trace != NULL)
    {
        fprintf(
            trace,
            "%u,%s,%u,%lu,%u,%u,%u,%lu\n",
            calls,
            runnable,
            (unsigned)Rte_Buf_DemoSwc_Button1_Button1,
            (unsigned long)Rte_Buf_DemoSwc_MotorNtc_mV_MotorNtc_mV,
            (unsigned)Rte_Buf_CanQlf_PC_Command,
            (unsigned)Rte_Buf_DemoSwc_Led1_Led1,
            (unsigned)Rte_Buf_DemoSwc_Led2_Led2,
            (unsigned long)Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV);
    }
}

static void call10ms(void)
{
    Run10ms();
    traceCall("Run10ms");
}

static void call100ms(void)
{
    Run100ms();
    traceCall("Run100ms");
}

static void buttonDrivesLed1(void)
{
    Rte_Buf_DemoSwc_Button1_Button1 = 1U;
    call10ms();
    CHECK(Rte_Buf_DemoSwc_Led1_Led1 == 1U);
    Rte_Buf_DemoSwc_Button1_Button1 = 0U;
    call10ms();
    CHECK(Rte_Buf_DemoSwc_Led1_Led1 == 0U);
}

static void led2BlinksWithOneHertz(void)
{
    /* Led2 toggles when the 0..49 counter wraps: 50 calls of Run10ms = 500 ms per edge. */
    int edges        = 0;
    int lastEdge     = -1;
    int wrongSpacing = 0;
    boolean previous = Rte_Buf_DemoSwc_Led2_Led2;
    for (int call = 0; call < 1000; ++call)
    {
        call10ms();
        if (Rte_Buf_DemoSwc_Led2_Led2 != previous)
        {
            if ((lastEdge >= 0) && ((call - lastEdge) != 50))
            {
                ++wrongSpacing;
            }
            lastEdge = call;
            ++edges;
            previous = Rte_Buf_DemoSwc_Led2_Led2;
        }
    }
    CHECK(edges == 20);
    CHECK(wrongSpacing == 0);
}

/* COM-13: the qualifier of PC_Command releases the blink of Led2. Precondition when this runs:
 * 1002 calls of Run10ms have passed, the last toggle of the blink state was at call 1001 and the
 * next one is due at call 1051 - so the 10 calls below stay inside one half period, and every
 * change of Led2 comes from the qualifier, not from the blink. Led1 has to stay unaffected. */
static void led2IsReleasedByTheQualifier(void)
{
    static uint8 const errors[] = {QLF_ERROR_CRC, QLF_ERROR_ALIVE, QLF_ERROR_TIMEOUT};

    Rte_Buf_CanQlf_PC_Command = QLF_OK;
    call10ms();
    CHECK(Rte_Buf_DemoSwc_Led2_Led2 == 1U); /* anchor: blink state is on and released */

    for (unsigned i = 0U; i < (sizeof(errors) / sizeof(errors[0])); ++i)
    {
        Rte_Buf_CanQlf_PC_Command = errors[i];
        call10ms();
        CHECK(Rte_Buf_DemoSwc_Led2_Led2 == 0U);
        Rte_Buf_CanQlf_PC_Command = QLF_OK;
        call10ms();
        CHECK(Rte_Buf_DemoSwc_Led2_Led2 == 1U); /* healing keeps the phase of the blink */
    }

    Rte_Buf_CanQlf_PC_Command = QLF_DEBOUNCE; /* nothing valid received yet is no release either */
    call10ms();
    CHECK(Rte_Buf_DemoSwc_Led2_Led2 == 0U);

    /* bus error, and Led1 keeps following Button1 while Led2 is blocked */
    Rte_Buf_CanQlf_PC_Command = QLF_ERROR;
    Rte_Buf_DemoSwc_Button1_Button1 = 1U;
    call10ms();
    CHECK(Rte_Buf_DemoSwc_Led2_Led2 == 0U);
    CHECK(Rte_Buf_DemoSwc_Led1_Led1 == 1U);

    Rte_Buf_CanQlf_PC_Command       = QLF_OK;
    Rte_Buf_DemoSwc_Button1_Button1 = 0U;
    call10ms();
    CHECK(Rte_Buf_DemoSwc_Led2_Led2 == 1U);
    CHECK(Rte_Buf_DemoSwc_Led1_Led1 == 0U);
}

static void ntcFilterConverges(void)
{
    Rte_Buf_DemoSwc_MotorNtc_mV_MotorNtc_mV = 1000U;
    call100ms();
    CHECK(Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV == 125U); /* 0 + (1000 - 0) / 8 */
    for (int i = 0; i < 100; ++i)
    {
        call100ms();
    }
    CHECK(Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV == 1000U);
    Rte_Buf_DemoSwc_MotorNtc_mV_MotorNtc_mV = 0U;
    call100ms();
    CHECK(Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV == 875U);
}

int main(int argc, char** argv)
{
    if (argc > 1)
    {
        trace = fopen(argv[1], "w");
        if (trace == NULL)
        {
            printf("cannot open trace file %s\n", argv[1]);
            return 2;
        }
        fprintf(trace, "call,runnable,Button1,MotorNtc_mV,PcCommandQlf,Led1,Led2,MotorNtcFiltered_mV\n");
    }
    DemoSwc_Init();
    /* The blink of Led2 is released by the qualifier of PC_Command (COM-13); QLF_OK from the first
     * call on keeps the behaviour of the three original test cases unchanged. */
    Rte_Buf_CanQlf_PC_Command = QLF_OK;
    buttonDrivesLed1();
    led2BlinksWithOneHertz();
    led2IsReleasedByTheQualifier();
    ntcFilterConverges();
    if (trace != NULL)
    {
        fclose(trace);
        printf("trace: %u calls written to %s\n", calls, argv[1]);
    }
    printf("%d checks, %d failures\n", checks, failures);
    return (failures == 0) ? 0 : 1;
}
